    image_patch = ImagePatch(image)
    horses = image_patch.find("horse")
    men = image_patch.find("man")

    if not horses or not men:
        return image_patch

    man_patches_sorted_by_horizontal_center = sorted(men, key=lambda m: m.horizontal_center)

