        return image_patch

    pizza_centers = [(p.left + p.right) / 2, (p.upper + p.lower) / 2 for p in pizza_patches]
    spinach_centers = [(s.left + s.right) / 2, (s.upper + s.lower) / 2 for s in spinach_patches]

