def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bananas = image_patch.find("banana")
    sandwiches = image_patch.find("sandwich")

    if not bananas or not sandwiches:
        return image_patch

    banana_patches = [b for b in bananas if b.verify_property("banana", "cut up")]
    sandwich_patches = [s for s in sandwiches if s.verify_property("sandwich", "first half")]

    if not banana_patches or not sandwich_patches:
        return image_patch

    banana_patches.sort(key=lambda p: p.horizontal_center)
    sandwich_patches.sort(key=lambda p: p.horizontal_center)

    left_half_sandwiches = sandwich_patches[:max(1, len(sandwich_patches) // 2)]

    for sandwich in left_half_sandwiches:
        for banana in banana_patches:
            if is_between_3d(banana, sandwich, sandwich):
                return banana

    return banana_patches[0]

