def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    food_patches = image_patch.find("food")
    plate_patches = image_patch.find("plate")

    if not food_patches or not plate_patches:
        return image_patch

    plate_depths = [(p, p.compute_depth()) for p in plate_patches]
    sorted_plates = sorted(plate_depths, key=lambda x: x[1], reverse=True)

    for plate, _ in sorted_plates:
        if plate.verify_property("plate", "brown"):
            food_above_plate = [f for f in food_patches if f.overlaps_with(*plate.bbox)]
            if food_above_plate:
                return food_above_plate[0]

    return food_patches[0]

