modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bench_patches = image_patch.find("bench")
    scissors_patches = image_patch.find("scissors")

    if not bench_patches or not scissors_patches:
        return image_patch

    min_distance = float('inf')
    closest_bench = None

    for bench in bench_patches:
        for scissors in scissors_patches:
            dist = abs(bench.horizontal_center - scissors.horizontal_center)
            if dist < min_distance:
                min_distance = dist
                closest_bench = bench

    return closest_bench

