modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    yogurt_patches = image_patch.find("yogurt")
    orange_slice_patches = image_patch.find("orange slice")
    candy_patches = image_patch.find("candy")

    if not yogurt_patches or not orange_slice_patches or not candy_patches:
        return image_patch

    yogurt_center = sum(p.vertical_center for p in yogurt_patches) / len(yogurt_patches)
    orange_slice_center = sum(p.vertical_center for p in orange_slice_patches) / len(orange_slice_patches)
    candy_center = sum(p.vertical_center for p in candy_patches) / len(candy_patches)

    if yogurt_center < orange_slice_center < candy_center:
        return candy_patches[0]
    elif orange_slice_center < yogurt_center < candy_center:
        return candy_patches[0]
    else:
        return image_patch

