def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    yogurt_patches = image_patch.find("yogurt")
    orange_slice_patches = image_patch.find("orange slice")
    candy_patches = image_patch.find("candy")

    if not yogurt_patches or not orange_slice_patches or not candy_patches:
        return image_patch

    # Find the patch of yogurt that has orange slices and candy nearby
    best_yogurt_patch = None
    min_distance = float('inf')

    for yogurt_patch in yogurt_patches:
        for orange_slice_patch in orange_slice_patches:
            for candy_patch in candy_patches:
                dist = distance(yogurt_patch, orange_slice_patch) + distance(yogurt_patch, candy_patch)
                if dist < min_distance:
                    min_distance = dist
                    best_yogurt_patch = yogurt_patch

    return best_yogurt_patch

