modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    container_patches = image_patch.find("container")
    orange_patches = image_patch.find("oranges")

    if not container_patches or not orange_patches:
        return image_patch

    container_patches.sort(key=lambda p: p.compute_depth(), reverse=True)
    orange_patches.sort(key=lambda p: p.compute_depth())

    container = container_patches[0]
    oranges = orange_patches[0]

    if container.verify_property("container", "plastic") and container.verify_property("container", "white"):
        if oranges.overlaps_with(container.left, container.lower, container.right, container.upper):
            return container
        else:
            return oranges

    return image_patch

modern_c4_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    container_patches = image_patch.find("container")
    orange_patches = image_patch.find("orange")

    if not container_patches or not orange_patches:
        return image_patch

    white_plastic_containers = [c for c in container_patches if c.verify_property("container", "white plastic")]

    if not white_plastic_containers:
        return image_patch

    containers_with_oranges = [c for c in white_plastic_containers if any(distance(c, o) < 10 for o in orange_patches)]

    if not containers_with_oranges:
        return image_patch

    return containers_with_oranges[0]

